SELECT request_control_command_id, req_ctrl_cmd_type, req_ctrl_cmd_time, req_ctrl_cmd_status, result_callback_url, req_ctrl_cmd, msa_identifier, req_identifier, transmission_status, transmission_time, req_status_change_time FROM msa_request_control_command_info where 1=1
and request_control_command_id = #{requestControlCommandId}
and req_ctrl_cmd_status = #{reqCtrlCmdStatus}
order by request_control_command_id desc

SELECT request_control_command_id, req_ctrl_cmd_type, req_ctrl_cmd_time, req_ctrl_cmd_status, result_callback_url, req_ctrl_cmd, msa_identifier, req_identifier, transmission_status, transmission_time, req_status_change_time FROM msa_request_control_command_info where 1=1
and request_control_command_id = #{requestControlCommandId}
and
req_ctrl_cmd_status = #{item}
and req_ctrl_cmd_status = #{reqCtrlCmdStatusErr}
order by request_control_command_id desc
